// Returns the brand icon for a tool name (exact match, or "name <version>" such as "Next.js 16")
export function getBrandIcon(name = '') {
  const norm = String(name).toLowerCase().trim();
  if (BRAND_ICONS[norm]) return BRAND_ICONS[norm];
  const key = Object.keys(BRAND_ICONS).find((k) => norm.startsWith(k + ' '));
  return key ? BRAND_ICONS[key] : null;
}

// On dark backgrounds, dark brand colours disappear, so they are drawn in white instead
export function brandColor(hex, onLight = false) {
  if (onLight) return '#' + hex;
  const r = parseInt(hex.slice(0, 2), 16);
  const g = parseInt(hex.slice(2, 4), 16);
  const b = parseInt(hex.slice(4, 6), 16);
  const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return luminance < 0.32 ? '#FFFFFF' : '#' + hex;
}
